#include <vector>
#include <algorithm>

class Solution {
public:
    int countLargestGroup(int n) {
        std::vector<int> counts(37, 0);
        for (int i = 1; i <= n; ++i) {
            int s = 0, temp = i;
            while (temp > 0) {
                s += temp % 10;
                temp /= 10;
            }
            counts[s]++;
        }
        int maxSize = *std::max_element(counts.begin(), counts.end());
        int res = 0;
        for (int sz : counts) if (sz == maxSize) res++;
        return res;
    }
};

class Solution {
    public int countLargestGroup(int n) {
        int[] counts = new int[37];
        for (int i = 1; i <= n; i++) {
            int s = 0, temp = i;
            while (temp > 0) {
                s += temp % 10;
                temp /= 10;
            }
            counts[s]++;
        }
        int maxSize = 0;
        for (int sz : counts) if (sz > maxSize) maxSize = sz;
        int res = 0;
        for (int sz : counts) if (sz == maxSize) res++;
        return res;
    }
}

var countLargestGroup = function(n) {
    const counts = new Array(37).fill(0);
    for (let i = 1; i <= n; i++) {
        let s = 0, temp = i;
        while (temp > 0) {
            s += temp % 10;
            temp = Math.floor(temp / 10);
        }
        counts[s]++;
    }
    const maxSize = Math.max(...counts);
    return counts.filter(sz => sz === maxSize).length;
};
